const rows=abs.filter(x=>{const s=x.sessions||{};const fullName=x.profiles?.full_name||'';return(!date||s.session_date===date)&&(!location||s.locations?.name===location)&&(!sport||s.sports?.name===sport)&&(!session||String(s.id)===session)&&(!player||fullName.toLowerCase().includes(player.toLowerCase()))});const unique=(key:string)=>Array.from(new Set((key==='location'?sessions.map((x:any)=>x.locations?.name):key==='sport'?sessions.map((x:any)=>x.sports?.name):rows.map(x=>x.profiles?.full_name)).filter(Boolean))).sort();const groups=rows.reduce((acc:any[],x:any)=>{const s=x.sessions||{};const key=s.session_date+'|'+(s.locations?.name||'')+'|'+(s.start_time||'');let g=acc.find(y=>y.key===key);if(!g){g={key,date:s.session_date,location:s.locations?.name||'Unknown location',time:s.start_time||'',end:s.end_time||'',players:[]};acc.push(g)}g.players.push(x.profiles?.full_name||x.profiles?.email||'Unknown player');return acc},[]);groups.sort((a:any,b:any)=>String(a.key).localeCompare(String(b.key)));const sessionOptions=sessions.filter((s:any)=>(!date||s.session_date===date)&&(!location||s.locations?.name===location)&&(!sport||s.sports?.name===sport)).sort((a:any,b:any)=>String(a.session_date+a.start_time).localeCompare(String(b.session_date+b.start_time)));const activityDates=Array.from(new Set(sessions.map((x:any)=>x.session_date).filter(Boolean))).sort();
